mapper.select:
SELECT
    memory_folders.id AS id,
    memory_folders.memory_id AS memoryId,
    memory_folders.folder_id AS folderId,
    memory_folders.created_at AS createdAt
FROM memory_folders

    AND memory_folders.memory_id = #{memoryId}
    AND memory_folders.folder_id = #{folderId}
    AND memory_folders.created_at = #{createdAt}

ORDER BY memory_folders.id ASC
